def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        base = DAILY_SALARY * 0.22
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    highest_prev = 0.0
    bob_prev = 0.0
    urgent_opp = 0
    rich_opp = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_opp += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if isinstance(bid, (int, float)):
            if bid > highest_prev:
                highest_prev = float(bid)
            if oid == 'Bob':
                bob_prev = float(bid)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    base = DAILY_SALARY * (0.28 + 0.22 * scarcity)

    if highest_prev > 0:
        if hp >= 7 and no_water == 0 and supply >= 20:
            target = max(base, highest_prev * 0.58)
        elif hp >= 5 and no_water == 0:
            target = max(base, highest_prev * 0.72)
        else:
            target = max(base, highest_prev * 0.92 + 1.0)
    else:
        target = base

    if bob_prev >= DAILY_SALARY * 1.5 and hp >= 6 and no_water == 0:
        target = min(target, bob_prev * 0.62)

    if urgent_opp >= 2 and hp >= 6 and no_water == 0:
        target *= 0.92

    if rich_opp == 1 and hp <= 4:
        target = max(target, DAILY_SALARY * 0.9)

    if hp <= 2:
        target = max(target, DAILY_SALARY * (0.95 + 0.15 * scarcity))
    elif hp <= 4 or no_water >= 1:
        target = max(target, DAILY_SALARY * (0.78 + 0.12 * scarcity))

    if supply >= 23 and hp >= 6 and no_water == 0:
        target *= 0.88
    elif supply <= 17:
        target *= 1.08

    if day >= 8:
        if hp >= 6 and no_water == 0:
            target *= 0.95
        else:
            target *= 1.05

    min_survival = 0.0
    if hp <= 2:
        min_survival = DAILY_SALARY * 0.9
    elif hp <= 4 or no_water >= 1:
        min_survival = DAILY_SALARY * 0.72

    bid = max(target, min_survival)
    bid = min(budget, bid)
    if budget < DAILY_SALARY * 0.35 and hp >= 5 and no_water == 0:
        bid = min(bid, budget * 0.7)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents only
    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            pass

    # If no opponents, bid conservatively
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely available; use this only to tune aggressiveness
    # (We don't know exact consumption mapping, but higher supply means we can bid less.)
    approx_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Pressure model from yesterday: if someone bid very high, match just enough to compete.
    # Alex's behavior indicates threshold around ~0.85*DAILY_SALARY.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Base target bid depending on supply
    if supply <= float(MIN_SUPPLY) + 0.5:
        base = DAILY_SALARY * 0.65
    elif supply >= float(MAX_SUPPLY) - 0.5:
        base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.55

    # If yesterday someone was extremely aggressive, increase bid to avoid being the next to die.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if hp > 3.0:
            target = max(base, highest_prev_bid * 0.55 + 0.15 * DAILY_SALARY)
        else:
            target = max(base, highest_prev_bid * 0.75 + 0.1 * DAILY_SALARY)
    else:
        # Otherwise, slightly over base or near the leader to secure at least one allocation.
        target = max(base, highest_prev_bid + 2.0)

    # If my HP is low, bid higher; if HP is high, bid slightly lower.
    if hp <= 2.0:
        target *= 1.15
    elif hp >= 6.0:
        target *= 0.95

    # If supply is scarce (few units), bid more.
    if approx_units <= 1:
        target *= 1.08

    # Final cap by budget
    bid = float(min(budget, target))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0
    if my_status['hp'] < 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)
    if supply > 20:
        return min(my_status['budget'], DAILY_SALARY * 0.6)
    if supply < 18:
        return min(my_status['budget'], avg_opp_bid * 1.05)
    return min(my_status['budget'], avg_opp_bid * 0.9)
